import React, { useState } from "react";
import "../Dashboard/WeatherDashboard.css"
import { useEffect } from "react";
import "./WeatherResults.css"; // Import the CSS file
import "../styles/global.css";
import "../styles/variables.scss";
import "../styles/utility.scss";

const WeatherResults = ({ results, hourlyResults}) => {
    const [temp, setTemp] = useState([]);
    const celsius = ((temp - 32) * 5/9).toFixed(0);
    const location = results.name;
    const [weatherDescription, setWeatherDescription] = useState([]);
    // convertToCamelCase(results.weather[0].main);
    const [highest, setHighest] = useState([]);
    // (parseInt(results.main.temp_min) - 273.15).toFixed(2);
    const [lowest, setLowest] = useState([]);
    // (parseInt(results.main.temp_max) - 273.15).toFixed(2);
    const [hourlyData, setHourlyData] = useState([]);
    const [hourlytempInF, setHourlytempInF] = useState([]);
    const currentHours = new Date().getHours();
    const [currentUVIndex, setCurrentUVIndex] = useState([]);
    let time;
    let hourlyTemp;
    const sunrise = hourlyResults?.days[0].sunrise;
    const sunset = hourlyResults?.days[0].sunset;
    const windSpeed = hourlyResults?.days[0].windspeed;
    const precipitation = hourlyResults?.days[0].precip;
    const humidity = hourlyResults?.days[0].humidity;
    // const images = [
    //     { src: require('./assets/clear-day.png'), alt: 'Image 1 Description' },
    //     { src: require('./assets/clear-night.png'), alt: 'Image 2 Description' },
    //     { src: require('./assets/cloudy.png'), alt: 'Image 1 Description' },
    //     { src: require('./assets/fog.png'), alt: 'Image 2 Description' },
    //     { src: require('./assets/hail.png'), alt: 'Image 1 Description' },
    //     { src: require('./assets/partly-cloudy-day.png'), alt: 'Image 2 Description' },
    //     { src: require('./assets/partly-cloudy-night.png'), alt: 'Image 1 Description' },
    //     { src: require('./assets/rain-snow-showers-day.png'), alt: 'Image 2 Description' },
    //     { src: require('./assets/rain-snow-showers-night.png'), alt: 'Image 1 Description' },
    //     { src: require('./assets/rain-snow.png'), alt: 'Image 2 Description' },
    //     { src: require('./assets/rain.png'), alt: 'Image 1 Description' },
    //     { src: require('./assets/showers-day.png'), alt: 'Image 2 Description' },
    //     { src: require('./assets/showers-night.png'), alt: 'Image 1 Description' },
    //     { src: require('./assets/sleet.png'), alt: 'Image 2 Description' },
    //     { src: require('./assets/snow-showers-day.png'), alt: 'Image 2 Description' },
    //     { src: require('./assets/snow-showers-night.png'), alt: 'Image 2 Description' },
    //     { src: require('./assets/snow.png'), alt: 'Image 2 Description' },
    //     { src: require('./assets/sleet.png'), alt: 'Image 2 Description' },
    //     { src: require('./assets/sleet.png'), alt: 'Image 2 Description' },
    //     { src: require('./assets/sleet.png'), alt: 'Image 2 Description' },
    //     { src: require('./assets/sleet.png'), alt: 'Image 2 Description' },
    //     { src: require('./assets/sleet.png'), alt: 'Image 2 Description' },
    // ]

    const convertFtoC = (temp) =>{
        return ((temp - 32) * 5/9).toFixed(0);
    }

    function getPngFileName(name){
        const fileName = '${name}.png';

    }
    const fetchHourlyWeather = () => {
        const tempData = [];
        const hours = hourlyResults?.days[0]?.hours;
        const index = hours.findIndex(hour =>{
            time = hour.datetime;
            const [hourPart] = time.split(':');
            return hourPart === currentHours.toString();

        });
        if(index !== -1){
            for(let i=index; i < hours.length && tempData.length < 25; i++){
                time = convertTo12HourFormat(hours[i].datetime);
                setHourlytempInF(hours[i].temp);
                setTemp(hourlyResults?.days[0].hours[index].temp);
                setCurrentUVIndex(hourlyResults?.days[0].hours[index].uvindex);
                setWeatherDescription(convertToCamelCase(hourlyResults?.days[0].hours[index].conditions));
                setHighest(convertFtoC(hourlyResults?.days[0].tempmax));
                setLowest(convertFtoC(hourlyResults?.days[0].tempmin));
                hourlyTemp = convertFtoC(hours[i].temp);
                tempData.push({time, hourlyTemp, hourlytempInF});
            }
            if(tempData.length <25){
                const secondhours = hourlyResults?.days[1]?.hours;
                for(let i = 0; i <secondhours.length && tempData.length <25; i++){
                    time = convertTo12HourFormat(secondhours[i].datetime);
                    setHourlytempInF(hours[i].temp);
                    hourlyTemp = convertFtoC(secondhours[i].temp);
                    tempData.push({time, hourlyTemp});
                }
            }
            setHourlyData(tempData);
        }    
    };

    const convertTo12HourFormat = (time) => {
        const [hours, minutes, seconds] = time.split(':');
        const hoursIn12Format = (hours % 12) || 12; // Convert 0 to 12 for midnight
        const ampm = hours < 12 ? 'am' : 'pm'; // Check the original hours for am/pm
        return time = hours?  `${hoursIn12Format}:${minutes}${ampm}` : 'null';     
    };

    function convertToCamelCase(str) {
        return str
            .toUpperCase()
            .split('')
            .map((word, index) => index === 0 ? word : word.charAt(0).toLowerCase() + word.slice(1))
            .join('');
    };

    useEffect(() => {
        if (hourlyResults) {
            fetchHourlyWeather(hourlyResults);
        }
    }, [hourlyResults]);


    return (
        <>
            <div className="card d-contents">
                <h2>{location}</h2>
                <h1>{celsius}&deg;C</h1>
                <p>{weatherDescription}</p>
                <div className="flex gap-lg">
                    <p>H: {highest} &deg;C</p>
                    <p>L: {lowest} &deg;C</p>
                </div>
            </div>

            <div>
                <ul className="flex list-none overflow-x gap-lg">
                    {hourlyData.map((data, index) => (
                            <div className="card">
                                <li className= "flex-column" key={index}>
                                   <p>{data.time}</p>
                                   <p> {data.hourlyTemp}°C</p>   
                                   <p> {hourlytempInF}°F</p>  
                                </li>
                            </div>

                    ))}   
                </ul>  
            </div>

            <div className="grid grid-template-columns gap-lg w-45">
                <div className="card">
                    <p>UV index</p>
                    <p>{currentUVIndex}</p>
                </div>
                <div className="card">
                    <p>SUNRISE</p>
                    <p>{sunrise} AM</p>
                </div>
                <div className="card">
                    <p>SUNSET</p>
                    <p>{sunset}</p>
                </div>
                <div className="card">
                    <p>HUMIDITY</p>
                    <p>{humidity}</p>
                </div>
                <div className="card">
                    <p>PRECIPITATION</p>
                    <p>{precipitation}</p>
                </div>
                <div className="card">
                    <p>WIND</p>
                    <p>{windSpeed}</p>
                </div>
            </div>


        </>
    );

}

export default WeatherResults;
